sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_amount;
uniform float amzp_waveScale;
uniform float amzp_stretchW;
uniform float amzp_turb;
uniform float amzp_riseSpeed;
uniform float amzp_riseAngle;
uniform float amzp_seed;
uniform float amzp_dispersion;
uniform float amzp_shimmer;
uniform float amzp_hazeBlur;
uniform float amzp_maskMode;
uniform float amzp_maskHeight;
uniform float amzp_maskSoft;
uniform float amzp_maskInv;
uniform float amzp_showMask;
uniform float amzp_detail;
uniform float amzp_samples;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float h21(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 17.13) * 43758.5453123); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), f.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float fbm(float2 p, float t) {
        float n = floor(clamp(amzp_detail, 1.0, 10.0) + 0.5);
        float s = 0.0, a = 0.5, ws = 0.0;
        for (int i = 0; i < 10; i++) {
            float fi = float(i);
            if (fi >= n) break;
            float2 drift = float2(sin(t * 0.7 + fi * 1.3), cos(t * 0.9 + fi * 2.1)) * amzp_turb * 0.6;
            s += a * vn(p + drift);
            ws += a;
            p = advRot(p, 0.6) * 2.03 + float2(1.7, 9.2);
            a *= 0.5;
        }
        return s / max(ws, 1e-5);
    }
    float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
    bool inL;
    float4 smp(float2 uv) { return inL ? layerClamp(uv) : layerAt(uv); }
    float heatMask(float2 uv, float4 orig) {
        float h = clamp(amzp_maskHeight, 0.0, 1.0);
        float sf = max(amzp_maskSoft, 0.001);
        float m = 1.0;
        if (int(amzp_maskMode) == 1) m = 1.0 - smoothstep(h * (1.0 - sf), h * (1.0 - sf) + sf * max(h, 0.05) + 0.001, uv.y);
        else if (int(amzp_maskMode) == 2) m = smoothstep(1.0 - h * (1.0 - sf) - sf * max(h, 0.05) - 0.001, 1.0 - h * (1.0 - sf), uv.y);
        else if (int(amzp_maskMode) == 3) {
            float l = orig.a > 0.0001 ? luma(orig.rgb / orig.a) : 0.0;
            float th = 1.0 - h;
            m = smoothstep(th - sf * 0.5, th + sf * 0.5 + 0.001, l);
        } else if (int(amzp_maskMode) == 4) {
            float2 W = layer;
            float d = length((uv - 0.5) * W) / max(length(W) * 0.5, 1.0);
            m = 1.0 - smoothstep(h * (1.0 - sf), h * (1.0 - sf) + sf * max(h, 0.05) + 0.001, d);
        }
        if ((amzp_maskInv>0.5) && int(amzp_maskMode) != 0) m = 1.0 - m;
        return clamp(m, 0.0, 1.0);
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        inL = uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0;
        float t = TT();
        float m = heatMask(uv, orig);
        float2 pp = uv * W / pxs();
        pp = advRot(pp, -radians(amzp_riseAngle));
        pp.y -= t * amzp_riseSpeed;
        float2 q = pp / max(amzp_waveScale, 1.0);
        q.y /= max(amzp_stretchW, 0.05);
        float tt = t * (0.5 + amzp_turb);
        float2 n = float2(fbm(q, tt), fbm(q + float2(19.7, 4.3), tt + 3.0)) - 0.5;
        float2 off = advRot(n * 2.0 * amzp_amount * pxs(), radians(amzp_riseAngle)) * m;
        float4 R;
        float N = floor(clamp(amzp_samples, 1.0, 64.0) + 0.5);
        float br = amzp_hazeBlur * pxs() * m;
        float4 acc = float4(0.0);
        float ws = 0.0;
        for (int i = 0; i < 64; i++) {
            float fi = float(i);
            if (fi >= N) break;
            float2 bo = float2(0.0);
            if (br > 0.01 && N > 1.0) {
                float a = fi * 2.39996323;
                bo = float2(cos(a), sin(a)) * br * sqrt((fi + 0.5) / N);
            }
            float2 o = off + bo;
            float4 s;
            if (amzp_dispersion > 0.0) {
                float4 sr = smp(uv + o * (1.0 + amzp_dispersion) / W);
                float4 sg = smp(uv + o / W);
                float4 sb = smp(uv + o * max(1.0 - amzp_dispersion, -1.0) / W);
                s = float4(sr.r, sg.g, sb.b, max(sg.a, max(sr.a, sb.a)));
            } else {
                s = smp(uv + o / W);
            }
            acc += s;
            ws += 1.0;
            if (br <= 0.01) break;
        }
        R = acc / max(ws, 1.0);
        if (amzp_shimmer > 0.0) {
            float sh = (n.x + n.y) * 0.8 * amzp_shimmer * m;
            R.rgb = clamp(R.rgb * (1.0 + sh), 0.0, 1.0) * step(0.0, R.a);
            R.rgb = min(R.rgb, float3(R.a));
        }
        if ((amzp_showMask>0.5)) R = float4(mix(R.rgb, float3(1.0, 0.1, 0.1) * max(R.a, 0.6), m * 0.6), max(R.a, m * 0.6));
        amzOutput = R;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
